import React, {useEffect, useState} from "react";
import api from "../api";

export default function Notices(){
  const [notes, setNotes] = useState([]);

  useEffect(()=>{
    // If backend has notices endpoint later, use it. For now hard-coded or from db if created.
    setNotes([
      {id:1,title:"Annual Sports Day - Jan 10, 2026",date:"2026-01-10",content:"All students should wear sports uniform"},
      {id:2,title:"Republic Day Holiday - Jan 26, 2026",date:"2026-01-26",content:"School will be closed"}
    ]);
  },[]);

  return (
    <div className="container">
      <div className="card">
        <h2 style={{color:"#005baa"}}>Notices</h2>
        {notes.map(n=>(
          <div key={n.id} style={{marginBottom:12}}>
            <h4>{n.title}</h4>
            <small>{new Date(n.date).toLocaleDateString()}</small>
            <p>{n.content}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
